import{_ as t,c as s,o as i,j as e,a as r}from"./chunks/framework.Dnh4IO1K.js";const f=JSON.parse('{"title":"卷一·7","description":"易小帖 - 卷一·7","frontmatter":{"title":"卷一·7","description":"易小帖 - 卷一·7"},"headers":[],"relativePath":"zh/classics/yixiaotie/007.md","filePath":"zh/classics/yixiaotie/007.md"}'),o={name:"zh/classics/yixiaotie/007.md"};function c(n,a,l,d,p,m){return i(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"卷一·7",tabindex:"-1"},[r("卷一·7 "),e("a",{class:"header-anchor",href:"#卷一·7","aria-label":"Permalink to “卷一·7”"},"​")],-1),e("p",null,"卦有列兩為對者，虞仲翔所謂旁通之卦，而孔氏《正義》名曰變卦，以陽變陰，陰變陽也。卦有合一而顛倒對者，王輔嗣所謂反對，而孔氏《正義》名曰覆卦。覆即反也。第伏羲畫卦，專取旁通，乾坤一旁通，六子三旁通，凡四旁通。而畫卦已畢。文王序卦專取覆卦，除乾坤、坎離、頤大過、小過中孚八卦外，凡五十六卦，作二十八覆卦，而六十四序卦已畢。但又有以旁通兼覆卦者，如泰否顛倒卦也，然併列之則三陰三陽正復旁通，推之而既未濟，歸妹漸，蠱隨皆然。然則易變可一端盡耶。",-1)])])}const h=t(o,[["render",c]]);export{f as __pageData,h as default};
